INSERT INTO sentences (id, content_id, position, start_ms, end_ms, text, normalized_text)
VALUES
  ('ielts_speaking_4_scores_s001', 'content_ielts_speaking_4_scores_datiyamemek', 1, 0, 4884, 'Stuck at a 6.5 in IELTS Speaking? Let''s fix it.', 'stuck at a 65 in ielts speaking lets fix it'),
  ('ielts_speaking_4_scores_s002', 'content_ielts_speaking_4_scores_datiyamemek', 2, 4884, 9140, 'Like writing, your speaking score averages four separate criteria.', 'like writing your speaking score averages four separate criteria'),
  ('ielts_speaking_4_scores_s003', 'content_ielts_speaking_4_scores_datiyamemek', 3, 9140, 14005, 'We''re going to walk through each one, find the two that are pulling your score down,', 'were going to walk through each one find the two that are pulling your score down'),
  ('ielts_speaking_4_scores_s004', 'content_ielts_speaking_4_scores_datiyamemek', 4, 14005, 18500, 'and look at specific drills that move them up to a band 7.', 'and look at specific drills that move them up to a band 7'),
  ('ielts_speaking_4_scores_s005', 'content_ielts_speaking_4_scores_datiyamemek', 5, 21500, 25159, 'Here are the four criteria for IELTS Speaking.', 'here are the four criteria for ielts speaking'),
  ('ielts_speaking_4_scores_s006', 'content_ielts_speaking_4_scores_datiyamemek', 6, 25159, 28779, 'Each is 25% of your final speaking score.', 'each is 25 of your final speaking score'),
  ('ielts_speaking_4_scores_s007', 'content_ielts_speaking_4_scores_datiyamemek', 7, 28779, 35980, 'Fluency and coherence. Can you speak at length without unnatural hesitation and do your ideas', 'fluency and coherence can you speak at length without unnatural hesitation and do your ideas'),
  ('ielts_speaking_4_scores_s008', 'content_ielts_speaking_4_scores_datiyamemek', 8, 35980, 43219, 'connect logically? Lexical resource. Do you use a range of vocabulary, including some less common', 'connect logically lexical resource do you use a range of vocabulary including some less common'),
  ('ielts_speaking_4_scores_s009', 'content_ielts_speaking_4_scores_datiyamemek', 9, 43219, 49879, 'phrases with natural collocation? Grammatical range and accuracy. Do you use a variety of', 'phrases with natural collocation grammatical range and accuracy do you use a variety of'),
  ('ielts_speaking_4_scores_s010', 'content_ielts_speaking_4_scores_datiyamemek', 10, 49879, 56879, 'structures, mostly correctly? Pronunciation. This is the one most students misunderstand.', 'structures mostly correctly pronunciation this is the one most students misunderstand'),
  ('ielts_speaking_4_scores_s011', 'content_ielts_speaking_4_scores_datiyamemek', 11, 56879, 58719, 'understand.', 'understand'),
  ('ielts_speaking_4_scores_s012', 'content_ielts_speaking_4_scores_datiyamemek', 12, 58719, 60780, 'Pronunciation isn''t about your accent.', 'pronunciation isnt about your accent'),
  ('ielts_speaking_4_scores_s013', 'content_ielts_speaking_4_scores_datiyamemek', 13, 60780, 66899, 'It''s about whether your speech is clear with appropriate word stress and natural intonation.', 'its about whether your speech is clear with appropriate word stress and natural intonation'),
  ('ielts_speaking_4_scores_s014', 'content_ielts_speaking_4_scores_datiyamemek', 14, 66899, 73380, 'If you''ve taken the test multiple times and your overall speaking is 6.5, two of those', 'if youve taken the test multiple times and your overall speaking is 65 two of those'),
  ('ielts_speaking_4_scores_s015', 'content_ielts_speaking_4_scores_datiyamemek', 15, 73380, 76539, 'four are sitting at a band 6.', 'four are sitting at a band 6'),
  ('ielts_speaking_4_scores_s016', 'content_ielts_speaking_4_scores_datiyamemek', 16, 76539, 86479, 'The job today is to find out which two and what the practical band 7 looks like for each.', 'the job today is to find out which two and what the practical band 7 looks like for each'),
  ('ielts_speaking_4_scores_s017', 'content_ielts_speaking_4_scores_datiyamemek', 17, 86479, 94559, 'number one, short answers in part one, and the related issue, hesitation in parts two and three.', 'number one short answers in part one and the related issue hesitation in parts two and three'),
  ('ielts_speaking_4_scores_s018', 'content_ielts_speaking_4_scores_datiyamemek', 18, 94559, 100920, 'Both come back to the fluency and coherence criterion. Look at this question. Do you enjoy', 'both come back to the fluency and coherence criterion look at this question do you enjoy'),
  ('ielts_speaking_4_scores_s019', 'content_ielts_speaking_4_scores_datiyamemek', 19, 100920, 109478, 'cooking? The short answer, yes, I enjoy cooking, is grammatically correct, but it''s also a band five.', 'cooking the short answer yes i enjoy cooking is grammatically correct but its also a band five'),
  ('ielts_speaking_4_scores_s020', 'content_ielts_speaking_4_scores_datiyamemek', 20, 109478, 116340, 'Why? Because it doesn''t give the examiner enough language to assess. Three words are not enough', 'why because it doesnt give the examiner enough language to assess three words are not enough'),
  ('ielts_speaking_4_scores_s021', 'content_ielts_speaking_4_scores_datiyamemek', 21, 116340, 122930, 'to sample your English. The fuller answer adds a reason, an example, and a recent experience.', 'to sample your english the fuller answer adds a reason an example and a recent experience'),
  ('ielts_speaking_4_scores_s022', 'content_ielts_speaking_4_scores_datiyamemek', 22, 122930, 130580, 'That''s the Band 7 pattern. Answer the question, give a reason, give an example. Three to four', 'thats the band 7 pattern answer the question give a reason give an example three to four'),
  ('ielts_speaking_4_scores_s023', 'content_ielts_speaking_4_scores_datiyamemek', 23, 130580, 138590, 'sentences per part one answer. Don''t memorize the sentences, memorize the pattern. For part two,', 'sentences per part one answer dont memorize the sentences memorize the pattern for part two'),
  ('ielts_speaking_4_scores_s024', 'content_ielts_speaking_4_scores_datiyamemek', 24, 138590, 159500, 'the cue card task the issue is usually different Students panic talk for 45 seconds and then run out of ideas The fix is to use the bullet points on the cue card as your structure Each bullet point is a guide Speak for about 30 seconds on each one If the cue card has three', 'the cue card task the issue is usually different students panic talk for 45 seconds and then run out of ideas the fix is to use the bullet points on the cue card as your structure each bullet point is a guide speak for about 30 seconds on each one if the cue card has three'),
  ('ielts_speaking_4_scores_s025', 'content_ielts_speaking_4_scores_datiyamemek', 25, 159500, 166500, 'bullets, you have 90 seconds before you even need to invent more. For part three, the discussion', 'bullets you have 90 seconds before you even need to invent more for part three the discussion'),
  ('ielts_speaking_4_scores_s026', 'content_ielts_speaking_4_scores_datiyamemek', 26, 166500, 174601, 'section, the issue is hesitation. Students freeze on questions that feel abstract. The fix is to use', 'section the issue is hesitation students freeze on questions that feel abstract the fix is to use'),
  ('ielts_speaking_4_scores_s027', 'content_ielts_speaking_4_scores_datiyamemek', 27, 174601, 181381, 'simple structure for every answer. Position, reason, example, and a tiny', 'simple structure for every answer position reason example and a tiny'),
  ('ielts_speaking_4_scores_s028', 'content_ielts_speaking_4_scores_datiyamemek', 28, 181381, 187541, 'conclusion. 20 seconds for the position and reason, 20 seconds for the example, 10', 'conclusion 20 seconds for the position and reason 20 seconds for the example 10'),
  ('ielts_speaking_4_scores_s029', 'content_ielts_speaking_4_scores_datiyamemek', 29, 187541, 193816, 'to wrap. That''s a band 7 shape part 3 answer.', 'to wrap thats a band 7 shape part 3 answer'),
  ('ielts_speaking_4_scores_s030', 'content_ielts_speaking_4_scores_datiyamemek', 30, 193816, 200581, 'Blocker number two is lexical resource, the vocabulary criterion. The trap here', 'blocker number two is lexical resource the vocabulary criterion the trap here'),
  ('ielts_speaking_4_scores_s031', 'content_ielts_speaking_4_scores_datiyamemek', 31, 200581, 206900, 'is the same one I covered in the writing video. Students think higher band means rare words.', 'is the same one i covered in the writing video students think higher band means rare words'),
  ('ielts_speaking_4_scores_s032', 'content_ielts_speaking_4_scores_datiyamemek', 32, 206900, 213780, 'That''s not what the criterion actually measures. Here''s what it actually measures. Range.', 'thats not what the criterion actually measures heres what it actually measures range'),
  ('ielts_speaking_4_scores_s033', 'content_ielts_speaking_4_scores_datiyamemek', 33, 213780, 218741, 'Do you use different words to describe similar things instead of repeating the same word?', 'do you use different words to describe similar things instead of repeating the same word'),
  ('ielts_speaking_4_scores_s034', 'content_ielts_speaking_4_scores_datiyamemek', 34, 220021, 226341, 'Collocation. Do words pair naturally the same way native speakers actually pair them?', 'collocation do words pair naturally the same way native speakers actually pair them'),
  ('ielts_speaking_4_scores_s035', 'content_ielts_speaking_4_scores_datiyamemek', 35, 226341, 235215, 'and idiomatic language. Can you use a few less common natural English phrases when they fit?', 'and idiomatic language can you use a few less common natural english phrases when they fit'),
  ('ielts_speaking_4_scores_s036', 'content_ielts_speaking_4_scores_datiyamemek', 36, 235215, 242401, 'What pulls students down to band six is leaning on general words. Good, bad, nice, important,', 'what pulls students down to band six is leaning on general words good bad nice important'),
  ('ielts_speaking_4_scores_s037', 'content_ielts_speaking_4_scores_datiyamemek', 37, 242401, 250101, 'many, a lot. If your answer to how was the meal is it was nice, very nice, the food was good,', 'many a lot if your answer to how was the meal is it was nice very nice the food was good'),
  ('ielts_speaking_4_scores_s038', 'content_ielts_speaking_4_scores_datiyamemek', 38, 250101, 254531, 'That''s band 5 territory, regardless of grammar.', 'thats band 5 territory regardless of grammar'),
  ('ielts_speaking_4_scores_s039', 'content_ielts_speaking_4_scores_datiyamemek', 39, 254531, 262815, 'Band 7 sounds like it was excellent, the flavors were unusual, and the portion size was generous for the price.', 'band 7 sounds like it was excellent the flavors were unusual and the portion size was generous for the price'),
  ('ielts_speaking_4_scores_s040', 'content_ielts_speaking_4_scores_datiyamemek', 40, 262815, 267750, 'Same idea, different vocabulary, more precise.', 'same idea different vocabulary more precise'),
  ('ielts_speaking_4_scores_s041', 'content_ielts_speaking_4_scores_datiyamemek', 41, 267750, 269271, 'The fix?', 'the fix'),
  ('ielts_speaking_4_scores_s042', 'content_ielts_speaking_4_scores_datiyamemek', 42, 269271, 272476, 'Build vocabulary and topic clusters.', 'build vocabulary and topic clusters'),
  ('ielts_speaking_4_scores_s043', 'content_ielts_speaking_4_scores_datiyamemek', 43, 272476, 276801, 'Family, work, hobbies, technology, health, the environment.', 'family work hobbies technology health the environment'),
  ('ielts_speaking_4_scores_s044', 'content_ielts_speaking_4_scores_datiyamemek', 44, 276801, 280481, 'These are all common speaking topics.', 'these are all common speaking topics'),
  ('ielts_speaking_4_scores_s045', 'content_ielts_speaking_4_scores_datiyamemek', 45, 280481, 288320, 'For each cluster, learn 10 to 15 natural phrases native speakers actually use,', 'for each cluster learn 10 to 15 natural phrases native speakers actually use'),
  ('ielts_speaking_4_scores_s046', 'content_ielts_speaking_4_scores_datiyamemek', 46, 288320, 307322, 'plus two or three idiomatic expressions not from a list but from actual English content This could be podcasts interviews or articles Make sure to notice how a host describes their hobby their work or their childhood That the vocabulary register', 'plus two or three idiomatic expressions not from a list but from actual english content this could be podcasts interviews or articles make sure to notice how a host describes their hobby their work or their childhood that the vocabulary register'),
  ('ielts_speaking_4_scores_s047', 'content_ielts_speaking_4_scores_datiyamemek', 47, 307322, 316442, 'that scores band seven. Blocker number three is grammatical range and accuracy. It''s the', 'that scores band seven blocker number three is grammatical range and accuracy its the'),
  ('ielts_speaking_4_scores_s048', 'content_ielts_speaking_4_scores_datiyamemek', 48, 316442, 322582, 'same principle as writing. You don''t need 10 new structures. You need a small set used', 'same principle as writing you dont need 10 new structures you need a small set used'),
  ('ielts_speaking_4_scores_s049', 'content_ielts_speaking_4_scores_datiyamemek', 49, 322582, 329702, 'naturally in the right context. Most students at 6.5 and speaking are using simple sentences', 'naturally in the right context most students at 65 and speaking are using simple sentences'),
  ('ielts_speaking_4_scores_s050', 'content_ielts_speaking_4_scores_datiyamemek', 50, 329702, 336501, 'almost exclusively. I work in marketing. I''ve been there for three years. I enjoy it. That''s', 'almost exclusively i work in marketing ive been there for three years i enjoy it thats'),
  ('ielts_speaking_4_scores_s051', 'content_ielts_speaking_4_scores_datiyamemek', 51, 336501, 344442, 'three short sentences, all simple. Band 7 mixes structures naturally. I''ve been working in', 'three short sentences all simple band 7 mixes structures naturally ive been working in'),
  ('ielts_speaking_4_scores_s052', 'content_ielts_speaking_4_scores_datiyamemek', 52, 344442, 350001, 'marketing for three years now, which I genuinely enjoy because it lets me use both the analytical', 'marketing for three years now which i genuinely enjoy because it lets me use both the analytical'),
  ('ielts_speaking_4_scores_s053', 'content_ielts_speaking_4_scores_datiyamemek', 53, 350001, 356582, 'and creative side of my thinking. Same content, different structure. The second version uses', 'and creative side of my thinking same content different structure the second version uses'),
  ('ielts_speaking_4_scores_s054', 'content_ielts_speaking_4_scores_datiyamemek', 54, 356582, 364182, 'present perfect continuous, a relative clause, a because clause, and a both and construction.', 'present perfect continuous a relative clause a because clause and a both and construction'),
  ('ielts_speaking_4_scores_s055', 'content_ielts_speaking_4_scores_datiyamemek', 55, 365242, 371516, 'None of those are advanced grammar. They''re what natural English actually sounds like.', 'none of those are advanced grammar theyre what natural english actually sounds like'),
  ('ielts_speaking_4_scores_s056', 'content_ielts_speaking_4_scores_datiyamemek', 56, 371516, 378021, 'Three structures to drill. The conditional. If I had more time, I''d probably take up photography', 'three structures to drill the conditional if i had more time id probably take up photography'),
  ('ielts_speaking_4_scores_s057', 'content_ielts_speaking_4_scores_datiyamemek', 57, 378021, 385702, 'again. The relative clause. My current job, which involves a lot of travel, can be tiring sometimes.', 'again the relative clause my current job which involves a lot of travel can be tiring sometimes'),
  ('ielts_speaking_4_scores_s058', 'content_ielts_speaking_4_scores_datiyamemek', 58, 386822, 393222, 'And the present perfect. I''ve been doing this for about five years. Practice weaving these into', 'and the present perfect ive been doing this for about five years practice weaving these into'),
  ('ielts_speaking_4_scores_s059', 'content_ielts_speaking_4_scores_datiyamemek', 59, 393222, 398521, 'sentences about your own life. The day of the test version of you should already be comfortable', 'sentences about your own life the day of the test version of you should already be comfortable'),
  ('ielts_speaking_4_scores_s060', 'content_ielts_speaking_4_scores_datiyamemek', 60, 398521, 403362, 'producing them without thinking. That''s where band seven grammar lives.', 'producing them without thinking thats where band seven grammar lives'),
  ('ielts_speaking_4_scores_s061', 'content_ielts_speaking_4_scores_datiyamemek', 61, 403362, 413122, 'Blocker number four is pronunciation, and this is the one most students misunderstand entirely.', 'blocker number four is pronunciation and this is the one most students misunderstand entirely'),
  ('ielts_speaking_4_scores_s062', 'content_ielts_speaking_4_scores_datiyamemek', 62, 413122, 420822, 'Pronunciation in IELTS is not about your accent. Examiners are trained to assess speakers from', 'pronunciation in ielts is not about your accent examiners are trained to assess speakers from'),
  ('ielts_speaking_4_scores_s063', 'content_ielts_speaking_4_scores_datiyamemek', 63, 420822, 429102, 'every English-speaking and non-English-speaking background. Your accent is fun. What pronunciation', 'every englishspeaking and nonenglishspeaking background your accent is fun what pronunciation'),
  ('ielts_speaking_4_scores_s064', 'content_ielts_speaking_4_scores_datiyamemek', 64, 429102, 434081, 'is actually measuring is whether you''re easy to understand and there are three', 'is actually measuring is whether youre easy to understand and there are three'),
  ('ielts_speaking_4_scores_s065', 'content_ielts_speaking_4_scores_datiyamemek', 65, 434081, 440141, 'components. The first is word stress. This is putting emphasis on the right', 'components the first is word stress this is putting emphasis on the right'),
  ('ielts_speaking_4_scores_s066', 'content_ielts_speaking_4_scores_datiyamemek', 66, 440141, 459947, 'syllable in the word Photograph photography photographic Same root different stress Wrong stress can make words confusing The second is sentence stress That means putting emphasis on the words in a sentence that carry the meaning', 'syllable in the word photograph photography photographic same root different stress wrong stress can make words confusing the second is sentence stress that means putting emphasis on the words in a sentence that carry the meaning'),
  ('ielts_speaking_4_scores_s067', 'content_ielts_speaking_4_scores_datiyamemek', 67, 459947, 463863, 'For example, if you say, I didn''t say she stole the money.', 'for example if you say i didnt say she stole the money'),
  ('ielts_speaking_4_scores_s068', 'content_ielts_speaking_4_scores_datiyamemek', 68, 463863, 468242, 'That sentence can have different meanings depending on which word you stress.', 'that sentence can have different meanings depending on which word you stress'),
  ('ielts_speaking_4_scores_s069', 'content_ielts_speaking_4_scores_datiyamemek', 69, 468242, 469483, 'Listen.', 'listen'),
  ('ielts_speaking_4_scores_s070', 'content_ielts_speaking_4_scores_datiyamemek', 70, 498242, 504682, 'I didn''t say she stole the money. I said she stole something else.', 'i didnt say she stole the money i said she stole something else'),
  ('ielts_speaking_4_scores_s071', 'content_ielts_speaking_4_scores_datiyamemek', 71, 504682, 509402, 'Number three is intonation. This is the rise and fall of your voice.', 'number three is intonation this is the rise and fall of your voice'),
  ('ielts_speaking_4_scores_s072', 'content_ielts_speaking_4_scores_datiyamemek', 72, 510402, 515203, 'Statements typically fall at the end. Genuine questions typically rise.', 'statements typically fall at the end genuine questions typically rise'),
  ('ielts_speaking_4_scores_s073', 'content_ielts_speaking_4_scores_datiyamemek', 73, 516203, 521823, 'A flat monotone delivery, even with perfect grammar, can sit at a band five or six in pronunciation', 'a flat monotone delivery even with perfect grammar can sit at a band five or six in pronunciation'),
  ('ielts_speaking_4_scores_s074', 'content_ielts_speaking_4_scores_datiyamemek', 74, 521823, 525602, 'because the examiner has to work harder to follow you.', 'because the examiner has to work harder to follow you'),
  ('ielts_speaking_4_scores_s075', 'content_ielts_speaking_4_scores_datiyamemek', 75, 525602, 536702, 'The fix? Shadowing. Take a one-minute clip of a native English speaker, a podcast host, a TED Talk, a news anchor, even me.', 'the fix shadowing take a oneminute clip of a native english speaker a podcast host a ted talk a news anchor even me'),
  ('ielts_speaking_4_scores_s076', 'content_ielts_speaking_4_scores_datiyamemek', 76, 536702, 542833, 'Listen to the sentence, then immediately repeat it, copying the rhythm exactly.', 'listen to the sentence then immediately repeat it copying the rhythm exactly'),
  ('ielts_speaking_4_scores_s077', 'content_ielts_speaking_4_scores_datiyamemek', 77, 542833, 549313, 'Stress the syllables they stress. Pause where they pause. Rise and fall where they do.', 'stress the syllables they stress pause where they pause rise and fall where they do'),
  ('ielts_speaking_4_scores_s078', 'content_ielts_speaking_4_scores_datiyamemek', 78, 549313, 552886, 'Do this for five minutes a day, every day.', 'do this for five minutes a day every day'),
  ('ielts_speaking_4_scores_s079', 'content_ielts_speaking_4_scores_datiyamemek', 79, 552886, 560153, 'This is the single most effective pronunciation drill there is, and don''t tell my boss, but it''s free.', 'this is the single most effective pronunciation drill there is and dont tell my boss but its free'),
  ('ielts_speaking_4_scores_s080', 'content_ielts_speaking_4_scores_datiyamemek', 80, 560153, 562316, 'Don''t try to change your accent.', 'dont try to change your accent'),
  ('ielts_speaking_4_scores_s081', 'content_ielts_speaking_4_scores_datiyamemek', 81, 562316, 566693, 'Do try to match the rhythm and stress of natural English.', 'do try to match the rhythm and stress of natural english'),
  ('ielts_speaking_4_scores_s082', 'content_ielts_speaking_4_scores_datiyamemek', 82, 566693, 568823, 'That''s what the examiner is listening for.', 'thats what the examiner is listening for'),
  ('ielts_speaking_4_scores_s083', 'content_ielts_speaking_4_scores_datiyamemek', 83, 568823, 571391, 'Quick note before we get into the routine.', 'quick note before we get into the routine'),
  ('ielts_speaking_4_scores_s084', 'content_ielts_speaking_4_scores_datiyamemek', 84, 571391, 575923, 'I turned the four criteria into a free drill pack you can actually do at home.', 'i turned the four criteria into a free drill pack you can actually do at home'),
  ('ielts_speaking_4_scores_s085', 'content_ielts_speaking_4_scores_datiyamemek', 85, 575923, 580063, 'one drill per criterion plus a part two template.', 'one drill per criterion plus a part two template'),
  ('ielts_speaking_4_scores_s086', 'content_ielts_speaking_4_scores_datiyamemek', 86, 580063, 581803, 'The link is in the description.', 'the link is in the description'),
  ('ielts_speaking_4_scores_s087', 'content_ielts_speaking_4_scores_datiyamemek', 87, 581803, 583763, 'Now let''s move on to the routine.', 'now lets move on to the routine'),
  ('ielts_speaking_4_scores_s088', 'content_ielts_speaking_4_scores_datiyamemek', 88, 586863, 589880, 'Let''s talk about a four week practice routine', 'lets talk about a four week practice routine'),
  ('ielts_speaking_4_scores_s089', 'content_ielts_speaking_4_scores_datiyamemek', 89, 589880, 592460, 'We move from a 6.5 to a 7.', 'we move from a 65 to a 7'),
  ('ielts_speaking_4_scores_s090', 'content_ielts_speaking_4_scores_datiyamemek', 90, 593560, 595535, 'Daily, 10 minutes.', 'daily 10 minutes'),
  ('ielts_speaking_4_scores_s091', 'content_ielts_speaking_4_scores_datiyamemek', 91, 595535, 597370, 'Five minutes of shadowing,', 'five minutes of shadowing'),
  ('ielts_speaking_4_scores_s092', 'content_ielts_speaking_4_scores_datiyamemek', 92, 597370, 601378, 'copying a native speaker''s rhythm, stress, and intonation.', 'copying a native speakers rhythm stress and intonation'),
  ('ielts_speaking_4_scores_s093', 'content_ielts_speaking_4_scores_datiyamemek', 93, 601378, 605099, 'And five minutes free speaking about a random topic', 'and five minutes free speaking about a random topic'),
  ('ielts_speaking_4_scores_s094', 'content_ielts_speaking_4_scores_datiyamemek', 94, 605099, 606925, 'recorded on your phone.', 'recorded on your phone'),
  ('ielts_speaking_4_scores_s095', 'content_ielts_speaking_4_scores_datiyamemek', 95, 606925, 609585, 'Talk for two minutes, then listen back.', 'talk for two minutes then listen back'),
  ('ielts_speaking_4_scores_s096', 'content_ielts_speaking_4_scores_datiyamemek', 96, 609585, 612160, 'You''re not editing yet, just listening.', 'youre not editing yet just listening'),
  ('ielts_speaking_4_scores_s097', 'content_ielts_speaking_4_scores_datiyamemek', 97, 613300, 615993, 'Three times a week, 20 minutes.', 'three times a week 20 minutes'),
  ('ielts_speaking_4_scores_s098', 'content_ielts_speaking_4_scores_datiyamemek', 98, 615993, 619430, 'Pick a part two cue card you haven''t seen.', 'pick a part two cue card you havent seen'),
  ('ielts_speaking_4_scores_s099', 'content_ielts_speaking_4_scores_datiyamemek', 99, 619430, 623840, 'Take one minute to plan, two minutes to speak, and record it.', 'take one minute to plan two minutes to speak and record it'),
  ('ielts_speaking_4_scores_s100', 'content_ielts_speaking_4_scores_datiyamemek', 100, 623840, 626640, 'Then listen back with this question.', 'then listen back with this question'),
